const sheetResponse = $input.first().json;
const rows = sheetResponse.values || [];
const headers = rows[0] || [];
const dataRows = rows.slice(1);

const packages = dataRows.map(row => {
  const obj = {};
  headers.forEach((h, i) => { obj[h] = row[i]; });
  return {
    packageId: obj.packageId || '',
    packageName: obj.packageName || '',
    destinationCountry: obj.destinationCountry || '',
    currencyCode: (obj.currencyCode || 'USD').toUpperCase(),
    basePriceUSD: parseFloat(obj.basePriceUSD) || 0,
    listedLocalPrice: parseFloat(obj.listedLocalPrice) || 0,
    lockedFXRate: parseFloat(obj.lockedFXRate) || 1,
    marginTargetPercent: parseFloat(obj.marginTargetPercent) || 20,
    maxAutoAdjustPercent: parseFloat(obj.maxAutoAdjustPercent) || 8,
    lastRepricedDate: obj.lastRepricedDate || ''
  };
}).filter(p => p.packageId);

let fxResponse = {};
try {
  fxResponse = $('HTTP Request - Fetch Current FX Rates').first().json;
} catch (e) {
  fxResponse = {};
}
const rates = fxResponse.rates || {};

const enriched = packages.map(p => ({
  ...p,
  currentFXRate: p.currencyCode === 'USD' ? 1 : (rates[p.currencyCode] || p.lockedFXRate),
  fxRateAvailable: p.currencyCode === 'USD' ? true : Boolean(rates[p.currencyCode])
}));

return enriched.map(p => ({ json: p }));

const p = $input.item.json;

const fxMovementPercent = p.lockedFXRate > 0
  ? Math.round(((p.currentFXRate - p.lockedFXRate) / p.lockedFXRate) * 10000) / 100
  : 0;

const targetLocalPrice = p.basePriceUSD * (1 + p.marginTargetPercent / 100) * p.currentFXRate;

const rawChangePercent = p.listedLocalPrice > 0
  ? Math.round(((targetLocalPrice - p.listedLocalPrice) / p.listedLocalPrice) * 10000) / 100
  : 0;

const maxAdj = p.maxAutoAdjustPercent;
const cappedChangePercent = Math.max(-maxAdj, Math.min(maxAdj, rawChangePercent));

const newListedLocalPrice = Math.round(p.listedLocalPrice * (1 + cappedChangePercent / 100) * 100) / 100;

const impliedMarginAfterRepricePercent = (p.currentFXRate > 0 && p.basePriceUSD > 0)
  ? Math.round((((newListedLocalPrice / p.currentFXRate) / p.basePriceUSD) - 1) * 10000) / 100
  : 0;

const needsManualReview = !p.fxRateAvailable
  || Math.abs(rawChangePercent - cappedChangePercent) > 0.01
  || Math.abs(fxMovementPercent) >= 15;

const revenueImpactUSD = p.currentFXRate > 0
  ? Math.round(((newListedLocalPrice - p.listedLocalPrice) / p.currentFXRate) * 100) / 100
  : 0;

return {
  json: {
    ...p,
    fxMovementPercent,
    rawChangePercent,
    cappedChangePercent,
    newListedLocalPrice,
    impliedMarginAfterRepricePercent,
    needsManualReview,
    revenueImpactUSD
  }
};

const allItems = $input.all().map(i => i.json);
const flagged = allItems.filter(p => p.needsManualReview);
const autoApplied = allItems.filter(p => !p.needsManualReview);

const totalRevenueImpactUSD = Math.round(
  allItems.reduce((sum, p) => sum + (p.revenueImpactUSD || 0), 0) * 100
) / 100;

return [{
  json: {
    runDate: new Date().toISOString(),
    totalPackages: allItems.length,
    allPackages: allItems,
    flaggedPackages: flagged,
    autoAppliedPackages: autoApplied,
    flaggedCount: flagged.length,
    autoAppliedCount: autoApplied.length,
    totalRevenueImpactUSD
  }
}];

parameters.text:
=You are a pricing risk analyst reviewing international packages whose FX-driven repricing was too large to apply automatically.

For each package below, the requested price change exceeded that package's own max-auto-adjust cap, its FX rate could not be confirmed, or the underlying FX movement since the rate was locked has been unusually large.

Flagged Packages (JSON):
{{ JSON.stringify($json.flaggedPackages) }}

For EACH package, reason about whether it is safe to apply the capped price now, whether the increase/decrease should be phased in over several days instead, or whether it should be held entirely for a human pricing lead to set manually. Ground your reasoning in the actual numbers given (fxMovementPercent, rawChangePercent, cappedChangePercent, impliedMarginAfterRepricePercent) rather than generic caution.

Return a JSON object with EXACTLY this field:
{
  "riskAssessments": [
    {
      "packageId": "matching packageId above",
      "packageName": "matching packageName above",
      "riskLevel": "Low|Medium|High",
      "recommendedAction": "Apply Capped Price|Phase Increase Over Several Days|Hold For Manual Pricing Review",
      "rationale": "One to two sentence, numbers-grounded explanation",
      "requiresManualApproval": true or false
    }
  ]
}

Return ONLY the JSON object. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
  if (!Array.isArray(parsed.riskAssessments)) throw new Error('missing riskAssessments');
} catch (e) {
  const flagged = item.flaggedPackages || [];
  parsed = {
    riskAssessments: flagged.map(p => ({
      packageId: p.packageId,
      packageName: p.packageName,
      riskLevel: 'High',
      recommendedAction: 'Hold For Manual Pricing Review',
      rationale: 'AI risk reasoning could not be parsed - defaulting to manual review as a precaution.',
      requiresManualApproval: true
    }))
  };
}

return {
  json: {
    ...item,
    riskAssessments: parsed.riskAssessments
  }
};

const item = $input.item.json;
const riskAssessments = item.riskAssessments || [];

const urgentReviewRequired = riskAssessments.some(r => r.requiresManualApproval === true);

return {
  json: {
    ...item,
    urgentReviewRequired
  }
};

parameters.text:
=You are a pricing analyst summarizing a daily FX repricing run for a marketing-ops Slack channel, not making the final call on your own.

Run Date: {{ $json.runDate }}
Total Packages Reviewed: {{ $json.totalPackages }}
Auto-Applied (within cap, no review needed): {{ $json.autoAppliedCount }}
Flagged For Review: {{ $json.flaggedCount }}
Total Revenue Impact (USD, this run): {{ $json.totalRevenueImpactUSD }}

Flagged Package Risk Assessments (JSON):
{{ JSON.stringify($json.riskAssessments) }}

Guidance: if flaggedCount is 0, the recommendation should be a clean pass-through. If any risk assessment recommends holding for manual review, the overall recommendation should not be a clean pass-through. Always ground your reasoning in the actual numbers above.

Return a JSON object with EXACTLY these fields:
{
  "overallRecommendation": "Proceed - Auto-Applied Prices Are Live|Proceed With Flags - Some Packages Held|Hold For Manual Pricing Review",
  "executiveSummary": "Two to four sentence summary of this run's FX exposure and what happened to prices",
  "slackSummaryMessage": "A concise, Slack-ready plain-text message (use simple line breaks, no markdown tables) summarizing the run for the pricing channel, including the auto-applied count, flagged count, and revenue impact",
  "recommendationConfidence": <number 0-100>
}

Return ONLY the JSON object. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    overallRecommendation: 'Hold For Manual Pricing Review',
    executiveSummary: 'Auto-flagged: could not parse AI synthesis output, defaulting to a cautious hold for manual review.',
    slackSummaryMessage: 'FX repricing run completed but the summary could not be generated automatically. Please review flagged packages manually in the PricingBook sheet.',
    recommendationConfidence: 30
  };
}

const loggedAt = new Date().toISOString();

return {
  json: {
    ...item,
    ...parsed,
    loggedAt,
    logSummaryRow: [
      item.runDate || '',
      item.totalPackages || 0,
      item.autoAppliedCount || 0,
      item.flaggedCount || 0,
      item.totalRevenueImpactUSD || 0,
      parsed.overallRecommendation || '',
      parsed.executiveSummary || '',
      loggedAt
    ]
  }
};

